        "metric_value": corr_coeff,
        "instances_tested": len(hord_values),
        "n_max": n,
        "conjecture_holds": conjecture_holds,
        "counterexample": "" if conjecture_holds else f"corr_coeff={corr_coeff}, abs_diff_mean={abs_diff_mean}"
    }

if __name__ == "__main__":
